def _rebase_push_jitter_sleep(attempt: int, sleep_fn: Callable[[float], None], rng: random.Random) -> None:
    base = 1 * (2 ** (attempt - 1))
    jitter = rng.randint(0, base // 2)
    sleep_for = base + jitter - base // 4
    sleep_fn(max(1, sleep_for))


